-- ============================================================================
-- SYNTHETIC CLAIMS & FRAUD NETWORK DATASET SQL DUMP
-- Minimum 500 Policyholders + Claims, Graph Network, & Fraud Vector Library
-- ============================================================================

BEGIN TRANSACTION;

-- ----------------------------------------------------------------------------
-- SCHEMA DEFINITIONS
-- ----------------------------------------------------------------------------

DROP TABLE IF EXISTS fraud_embeddings;
DROP TABLE IF EXISTS graph_edges;
DROP TABLE IF EXISTS graph_nodes;
DROP TABLE IF EXISTS claims;
DROP TABLE IF EXISTS devices;
DROP TABLE IF EXISTS bank_accounts;
DROP TABLE IF EXISTS service_providers;
DROP TABLE IF EXISTS policyholders;

CREATE TABLE policyholders (
    policyholder_id VARCHAR(36) PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    email VARCHAR(100),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE service_providers (
    provider_id VARCHAR(36) PRIMARY KEY,
    provider_name VARCHAR(100) NOT NULL,
    category VARCHAR(50) NOT NULL,
    risk_score DECIMAL(3,2)
);

CREATE TABLE bank_accounts (
    account_id VARCHAR(36) PRIMARY KEY,
    account_number VARCHAR(20) NOT NULL,
    routing_number VARCHAR(20) NOT NULL,
    bank_name VARCHAR(50)
);

CREATE TABLE devices (
    device_id VARCHAR(36) PRIMARY KEY,
    device_fingerprint VARCHAR(64) UNIQUE NOT NULL,
    ip_address VARCHAR(45),
    os VARCHAR(30)
);

CREATE TABLE claims (
    claim_id VARCHAR(36) PRIMARY KEY,
    policyholder_id VARCHAR(36) REFERENCES policyholders(policyholder_id),
    provider_id VARCHAR(36) REFERENCES service_providers(provider_id),
    device_id VARCHAR(36) REFERENCES devices(device_id),
    bank_account_id VARCHAR(36) REFERENCES bank_accounts(account_id),
    incident_date DATE NOT NULL,
    claimed_amount DECIMAL(10,2) NOT NULL,
    claim_status VARCHAR(20) DEFAULT 'PENDING',
    is_fraudulent BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE graph_nodes (
    node_id VARCHAR(36) PRIMARY KEY,
    node_type VARCHAR(30) NOT NULL, -- 'CLAIMANT', 'PROVIDER', 'BANK_ACCOUNT', 'DEVICE'
    entity_id VARCHAR(36) NOT NULL,
    label VARCHAR(100)
);

CREATE TABLE graph_edges (
    edge_id VARCHAR(36) PRIMARY KEY,
    source_node_id VARCHAR(36) REFERENCES graph_nodes(node_id),
    target_node_id VARCHAR(36) REFERENCES graph_nodes(node_id),
    relationship_type VARCHAR(50) NOT NULL, -- 'PAID_TO', 'CLAIMED_BY', 'USED_DEVICE', 'LINKED_TO'
    weight DECIMAL(3,2) DEFAULT 1.00
);

CREATE TABLE fraud_embeddings (
    library_id VARCHAR(36) PRIMARY KEY,
    pattern_type VARCHAR(100) NOT NULL,
    description TEXT NOT NULL,
    embedding JSONB NOT NULL, -- Stored as JSON array or Vector
    severity_level VARCHAR(20) NOT NULL
);


